<!doctype html>
<html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:11px;color:#222}.header{text-align:center;border-bottom:2px solid #17365d;padding-bottom:10px}.header h1{font-size:17px;margin:4px}.header h2{font-size:14px;margin:7px}.section{font-weight:bold;color:#fff;background:#17365d;padding:6px;margin-top:14px}table{width:100%;border-collapse:collapse;margin-top:8px}td{border:1px solid #777;padding:7px}.label{font-weight:bold;width:22%;background:#f1f4f8}.decision{margin-top:35px;width:42%;text-align:center;border-top:1px solid #222;padding-top:6px}</style></head><body>
<div class="header"><h1>Municipal Social Welfare and Development Office</h1><div>Tagudin, Ilocos Sur</div><h2>APPLICATION FOR ASSISTANCE</h2></div>
<div class="section">Application Details</div><table><tr><td class="label">Reference Code</td><td>{{ $beneficiary->reference_code }}</td><td class="label">Eligibility</td><td>{{ $beneficiary->eligibility_status }}</td></tr><tr><td class="label">Assistance Type</td><td>{{ $beneficiary->assistanceType?->name ?? 'N/A' }}</td><td class="label">Date of Assistance</td><td>{{ $beneficiary->date_of_assistance?->format('F d, Y') ?? 'N/A' }}</td></tr><tr><td class="label">Amount Requested / Granted</td><td colspan="3">PHP {{ number_format((float) ($beneficiary->amount ?? 0), 2) }}</td></tr></table>
<div class="section">Applicant Details</div><table><tr><td class="label">Name</td><td>{{ $beneficiary->name }}</td><td class="label">Age / Sex</td><td>{{ $beneficiary->age }} / {{ $beneficiary->sex }}</td></tr><tr><td class="label">Address</td><td colspan="3">{{ $beneficiary->address ?? 'N/A' }}, {{ $beneficiary->barangay?->name ?? 'N/A' }}</td></tr><tr><td class="label">Contact</td><td colspan="3">{{ $beneficiary->contact ?? 'N/A' }}</td></tr></table>
<div class="section">Assessment / Decision</div><table><tr><td class="label">Case Information</td><td>{{ $beneficiary->case_info ?? 'No narrative provided.' }}</td></tr><tr><td class="label">Encoded by</td><td>{{ $beneficiary->encoder?->name ?? 'N/A' }}</td></tr></table><div class="decision">Approving Officer Signature</div>
</body></html>
